#!/bin/bash
# the S3 bench (from S2's): ONE page (test&scene=12, the fake), q pinned, 8 s warm, a cold call discarded, then 3 interleaved quads
# benchFluid(300,null,'pool') / bands (K2 default: the mask OFF — the vort branch not taken) / bands with CURL_MASK 1 (the branch taken: a uniform, no new pass)
# / bands with a snare jet pending on every step (MS.snareEvt held: 1 + SNARE_N sjet splats a frame)
cd /home/toma/Documents/Kraftek/RetinaRave-wt-fluid2 || exit 1
E='{"eval":"CARD.benchFluid(300,null,\"pool\").toFixed(3)"},{"eval":"(CARD.fluid.K2.CURL_MASK=0,CARD.MS.snareEvt=0,CARD.benchFluid(300,null,\"bands\").toFixed(3)+\" ship \"+JSON.stringify(CARD.fluid.mids)+JSON.stringify(CARD.fluid.snare))"},{"eval":"(CARD.fluid.K2.CURL_MASK=1,CARD.benchFluid(300,null,\"bands\").toFixed(3)+\" mask \"+JSON.stringify(CARD.fluid.params.curlMask))"},{"eval":"(CARD.fluid.K2.CURL_MASK=0,CARD.MS.snareEvt=1,CARD.MS.snareAmp=0.9,CARD.benchFluid(300,null,\"bands\").toFixed(3)+\" snare-every-step \"+JSON.stringify(CARD.fluid.snare)+\" n \"+CARD.fluid.nSplat)"}'
GPU=1 PORT=8975 OUT=tools/work node tools/cdp.js "test&scene=12" "[{\"until\":\"window.CARD\"},{\"eval\":\"setInterval(()=>CARD.Q.q=0.95,16);'pinned'\"},{\"wait\":8000},{\"eval\":\"CARD.benchFluid(300,null,'pool').toFixed(3)+' cold'\"},$E,$E,$E,{\"eval\":\"(CARD.MS.snareEvt=0,CARD.bench(0,300).toFixed(3)+' nav')\"},{\"eval\":\"JSON.stringify({tier:CARD.fluid.tier,sim:[CARD.fluid.simW,CARD.fluid.simH],dye:[CARD.fluid.dyeW,CARD.fluid.dyeH],q:CARD.Q.q,g:CARD.fluid.grammar,errs:CARD.ERRS})\"}]" 2>&1 | grep -E "^EVAL|EXC|ERR" | sed 's/^EVAL //'
uptime
echo "== MOBILE=1 tier 0: scene 13 alive + the bench at tier 0 (the mask held, the jet held)"
MOBILE=1 GPU=1 PORT=8975 OUT=tools/work node tools/cdp.js "test&scene=13" "[{\"until\":\"window.CARD\"},{\"wait\":4000},{\"eval\":\"JSON.stringify({sc:CARD.SC.cur,g:CARD.fluid.grammar,tier:CARD.fluid.tier,sim:[CARD.fluid.simW,CARD.fluid.simH],dye:[CARD.fluid.dyeW,CARD.fluid.dyeH],errs:CARD.ERRS,bad:CARD.nonFinite(),frameN:CARD.frameN,mids:CARD.fluid.mids,snare:CARD.fluid.snare})\"},{\"eval\":\"CARD.benchFluid(300,null,'bands').toFixed(3)+' bands default'\"},{\"eval\":\"(CARD.fluid.K2.CURL_MASK=1,CARD.benchFluid(300,null,'bands').toFixed(3)+' bands mask')\"},{\"eval\":\"(CARD.fluid.K2.CURL_MASK=0,CARD.MS.snareEvt=1,CARD.MS.snareAmp=0.9,CARD.benchFluid(300,null,'bands').toFixed(3)+' bands snare-every-step')\"},{\"eval\":\"(CARD.MS.snareEvt=0,CARD.benchFluid(300,null,'pool').toFixed(3)+' pool')\"},{\"shot\":\"s3-mobile-s13\"},{\"eval\":\"JSON.stringify({errs:CARD.ERRS,bad:CARD.nonFinite(),tier:CARD.fluid.tier})\"}]" 2>&1 | grep -E "^EVAL|EXC|ERR" | sed 's/^EVAL //'
